reference_cedar:
permit (principal, action == Action::"viewAccessLog", resource is AccessLog)
when {
  context.session.user == principal &&
  context.session.isActive &&
  (
    (principal is Patient && resource.patient == principal) ||
    (
      context has representativeRelationship &&
      context.representativeRelationship.patient == resource.patient &&
      context.representativeRelationship.representative == principal &&
      context.representativeRelationship.isActive
    )
  )
};

permit (principal, action == Action::"viewMedicalRecord", resource is MedicalRecord)
when {
  context.session.user == principal &&
  context.session.isActive &&
  (
    (principal is Patient && resource.patient == principal) ||
    (
      context has representativeRelationship &&
      context.representativeRelationship.patient == resource.patient &&
      context.representativeRelationship.representative == principal &&
      context.representativeRelationship.isActive
    )
  )
};

permit (principal is PersonalRepresentative, action == Action::"viewMedicalRecord", resource is MedicalRecord)
when {
  context.session.user == principal &&
  context.session.isActive &&
  context has representativeRelationship &&
  context.representativeRelationship.patient == resource.patient &&
  context.representativeRelationship.representative == principal &&
  context.representativeRelationship.isActive
};

permit (principal is Lhcp, action == Action::"viewDiagnosticInformation", resource is DiagnosticInformation)
when {
  resource.isRestricted &&
  resource.allowedAudienceType == DiagnosticInformationAudience::"DesignatedLicensedHealthCareProfessionals" &&
  context has providerDesignation &&
  context.providerDesignation.patient == resource.patient &&
  context.providerDesignation.lhcp == principal &&
  context.providerDesignation.isDesignated
};
